
.home {
  padding: 14px;
  animation: fadeIn 0.35s var(--ease-out);
}

.home-hero {
  background: linear-gradient(135deg, #fffdf9, #f6efe4);
  border: 1px solid var(--border);
  border-left: 4px solid var(--accent);
  border-radius: var(--r-md);
  padding: 16px;
  margin-bottom: 14px;
  box-shadow: var(--shadow);
  position: relative;
  overflow: hidden;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    var(--shadow);
}
.home-hero.danger {
  border-left-color: var(--danger);
  animation: dangerPulse 1.6s ease-in-out infinite;
}
.home-hero.warn {
  border-left-color: var(--warning);
  animation: warnPulse 1.8s ease-in-out infinite;
}

/* 右上角印章 */
.stamp {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 48px;
  height: 48px;
  border: 2px solid var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: bold;
  color: var(--accent);
  opacity: 0.35;
  transform: rotate(-12deg);
  letter-spacing: 0.5px;
  text-align: center;
  line-height: 1.1;
  pointer-events: none;
}

.hero-top {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 4px;
}
.hero-name {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 900;
}
.hero-meta {
  font-size: 11px;
  color: var(--text-secondary);
}
.hero-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 8px 0 12px;
}
.tag {
  font-size: 10px;
  padding: 2px 8px;
  border-radius: var(--r-pill);
  background: var(--nav);
  color: var(--text-secondary);
  border: 1px solid rgba(140, 126, 108, 0.3);
}

/* ── 智能诊断 ── */
.diagnosis {
  background: linear-gradient(135deg, rgba(224, 73, 60, 0.06), rgba(226, 143, 27, 0.06));
  border: 1px solid rgba(224, 73, 60, 0.2);
  border-radius: var(--r-md);
  padding: 10px 14px;
  margin-bottom: 12px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text);
  cursor: pointer;
  transition: border-color 0.2s;
}
.diagnosis:hover {
  border-color: rgba(224, 73, 60, 0.4);
}
.diagnosis .d-icon {
  font-size: 14px;
  margin-right: 6px;
}
.diagnosis .d-severity {
  font-weight: 700;
  color: var(--danger);
}

/* ── 危机倒计时 ── */
.countdown-bar {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.countdown-chip {
  flex: 1;
  min-width: 100px;
  background: linear-gradient(135deg, rgba(224, 73, 60, 0.08), #fffdf9);
  border: 1px solid rgba(224, 73, 60, 0.25);
  border-radius: var(--r-md);
  padding: 8px 12px;
  text-align: center;
  animation: pulseGlow 2s ease-in-out infinite;
}
.countdown-chip.warn {
  background: linear-gradient(135deg, rgba(226, 143, 27, 0.08), #fffdf9);
  border-color: rgba(226, 143, 27, 0.25);
}
.cd-label {
  font-size: 10px;
  color: var(--text-secondary);
}
.cd-val {
  font-family: var(--font-data);
  font-size: 16px;
  font-weight: 700;
  color: var(--danger);
  margin-top: 2px;
}
.countdown-chip.warn .cd-val {
  color: #b06f12;
}

/* ── 三资源环 ── */
.rings-row {
  display: flex;
  justify-content: space-around;
  margin: 12px 0 16px;
  gap: 6px;
}
.ring-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  transition: transform 0.2s var(--ease-out);
}
.ring-wrap:hover {
  transform: translateY(-2px);
}
.ring-pos {
  position: relative;
}
.ring-svg {
  width: 60px;
  height: 60px;
  transform: rotate(-90deg);
  filter: drop-shadow(0 2px 4px rgba(44, 37, 32, 0.1));
}
.ring-bg {
  fill: none;
  stroke: rgba(140, 126, 108, 0.12);
  stroke-width: 5;
}
.ring-fill {
  fill: none;
  stroke-width: 5;
  stroke-linecap: round;
  transition:
    stroke-dashoffset 0.8s var(--ease-out),
    stroke 0.3s;
}
.ring-center {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  font-family: var(--font-data);
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
}
.ring-label {
  font-size: 10px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 3px;
  font-weight: 500;
}

/* ── 生存压力条 ── */
.pressure-bar-wrap {
  margin: 12px 0 16px;
  padding: 10px 14px;
  background: linear-gradient(135deg, rgba(224, 73, 60, 0.05), rgba(226, 143, 27, 0.05));
  border: 1px solid rgba(140, 126, 108, 0.15);
  border-radius: var(--r-md);
}
.pressure-bar-head {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--text-secondary);
  margin-bottom: 6px;
  font-weight: 500;
}
.pressure-bar {
  height: 10px;
  background: rgba(140, 126, 108, 0.12);
  border-radius: var(--r-pill);
  overflow: hidden;
  position: relative;
}
.pressure-fill {
  height: 100%;
  border-radius: var(--r-pill);
  background: linear-gradient(90deg, #4caf50, #e28f1b 50%, #e0493c);
  transition: width 0.6s var(--ease-out);
  position: relative;
  overflow: hidden;
}
.pressure-fill::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
  animation: shimmer 2.5s infinite linear;
}

/* ── 天气小卡 ── */
.weather-mini {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
  margin-bottom: 14px;
}
.wm-item {
  background: rgba(52, 138, 167, 0.05);
  border: 1px solid rgba(52, 138, 167, 0.15);
  border-radius: var(--r-md);
  padding: 8px 10px;
  text-align: center;
}
.wm-icon {
  font-size: 20px;
}
.wm-val {
  font-family: var(--font-data);
  font-size: 13px;
  font-weight: 700;
  margin-top: 2px;
}
.wm-lbl {
  font-size: 9px;
  color: var(--text-secondary);
  margin-top: 1px;
}

/* ── 灵力核心条：醒目，区别于 0-100 体征 ── */
.lingli-bar {
  margin: 6px 0 12px;
  padding: 10px 12px;
  border-radius: var(--r-md);
  background: linear-gradient(135deg, rgba(52, 138, 167, 0.06), rgba(168, 140, 52, 0.06));
  border: 1px solid rgba(52, 138, 167, 0.25);
  position: relative;
  overflow: hidden;
  transition:
    border-color 0.3s,
    box-shadow 0.3s;
}
.lingli-bar.lingli-枯竭 {
  border-color: rgba(224, 73, 60, 0.4);
  background: linear-gradient(135deg, rgba(224, 73, 60, 0.08), rgba(140, 126, 108, 0.04));
}
.lingli-bar.lingli-稀薄 {
  border-color: rgba(226, 143, 27, 0.35);
  background: linear-gradient(135deg, rgba(226, 143, 27, 0.06), rgba(140, 126, 108, 0.04));
}
.lingli-bar.lingli-正常 {
  border-color: rgba(52, 138, 167, 0.3);
}
.lingli-bar.lingli-旺盛 {
  border-color: rgba(76, 175, 80, 0.35);
  background: linear-gradient(135deg, rgba(76, 175, 80, 0.06), rgba(168, 140, 52, 0.04));
}
.lingli-bar.lingli-全盛 {
  border-color: rgba(201, 168, 76, 0.45);
  background: linear-gradient(135deg, rgba(201, 168, 76, 0.1), rgba(52, 138, 167, 0.04));
  animation: spiritGlow 2.5s ease-in-out infinite;
}

/* 九尾灵气光晕 + 灵气粒子（仅 旺盛/全盛 显示） */
.nine-tail-aura {
  position: absolute;
  inset: -20px;
  pointer-events: none;
  opacity: 1;
  background: radial-gradient(circle at 50% 50%, rgba(201, 168, 76, 0.15), transparent 70%);
  animation: breathe 4s ease-in-out infinite;
}
.spirit-particles {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  background-image:
    radial-gradient(circle at 20% 30%, rgba(201, 168, 76, 0.5) 1px, transparent 2px),
    radial-gradient(circle at 70% 60%, rgba(52, 138, 167, 0.4) 1px, transparent 2px),
    radial-gradient(circle at 45% 80%, rgba(201, 168, 76, 0.4) 1px, transparent 2px),
    radial-gradient(circle at 85% 25%, rgba(255, 255, 255, 0.5) 1px, transparent 2px);
  background-size:
    40px 40px,
    55px 55px,
    50px 50px,
    35px 35px;
  animation: float 5s ease-in-out infinite;
  opacity: 0.6;
}

.lingli-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
  position: relative;
  z-index: 1;
}
.ll-name {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}
.ll-rank {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--r-pill);
  background: rgba(52, 138, 167, 0.15);
  color: var(--info);
}
.lingli-bar.lingli-枯竭 .ll-rank {
  background: rgba(224, 73, 60, 0.15);
  color: var(--danger);
}
.lingli-bar.lingli-稀薄 .ll-rank {
  background: rgba(226, 143, 27, 0.15);
  color: #b06f12;
}
.lingli-bar.lingli-全盛 .ll-rank,
.lingli-bar.lingli-旺盛 .ll-rank {
  background: rgba(76, 175, 80, 0.15);
  color: var(--success);
}
.lingli-track {
  position: relative;
  height: 10px;
  border-radius: var(--r-pill);
  background: rgba(140, 126, 108, 0.15);
  overflow: visible;
  border: 1px solid rgba(140, 126, 108, 0.2);
  z-index: 1;
}
.lingli-fill {
  height: 100%;
  border-radius: var(--r-pill);
  background: linear-gradient(90deg, #348aa7, #6bb6c9 50%, #c9a84c);
  transition: width 0.4s var(--ease-out);
  box-shadow: 0 0 6px rgba(52, 138, 167, 0.3);
  position: relative;
  overflow: hidden;
}
.lingli-fill::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent);
  animation: shimmer 3s infinite linear;
}
.lingli-bar.lingli-枯竭 .lingli-fill {
  background: linear-gradient(90deg, #8b3a3a, #b84a4a);
  box-shadow: 0 0 6px rgba(224, 73, 60, 0.3);
}
.lingli-bar.lingli-稀薄 .lingli-fill {
  background: linear-gradient(90deg, #b06f12, #e28f1b);
  box-shadow: 0 0 6px rgba(226, 143, 27, 0.3);
}
.lingli-bar.lingli-全盛 .lingli-fill {
  background: linear-gradient(90deg, #4caf50, #8bc34a, #c9a84c);
  box-shadow: 0 0 10px rgba(201, 168, 76, 0.5);
}
.lingli-peak {
  position: absolute;
  top: -2px;
  width: 2px;
  height: 14px;
  background: var(--accent);
  border-radius: 1px;
  box-shadow: 0 0 4px rgba(168, 68, 52, 0.5);
}
.lingli-nums {
  display: flex;
  align-items: baseline;
  gap: 5px;
  margin-top: 5px;
  position: relative;
  z-index: 1;
}
.ll-val {
  font-family: var(--font-data);
  font-size: 16px;
  font-weight: 700;
  color: var(--info);
}
.ll-max {
  font-size: 10px;
  color: var(--text-secondary);
}
.ll-ratio {
  font-size: 10px;
  color: var(--text-secondary);
  margin-left: auto;
}

/* ── 警报 ── */
.alert-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 4px;
}
.alert {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 500;
  padding: 8px 11px;
  border-radius: var(--r-md);
  border: 1px solid;
  animation:
    fadeIn 0.3s var(--ease-out),
    pulseGlow 2.2s ease-in-out infinite;
}
.alert.danger {
  background: rgba(224, 73, 60, 0.08);
  border-color: rgba(224, 73, 60, 0.3);
  color: var(--danger);
}
.alert.warn {
  background: rgba(226, 143, 27, 0.08);
  border-color: rgba(226, 143, 27, 0.3);
  color: #b06f12;
}
.alert .a-ico {
  font-size: 15px;
  animation: float 2.5s ease-in-out infinite;
}

/* ── 六边形体征 ── */
.vitals-honeycomb {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 14px;
}
.hex-card {
  position: relative;
  background: var(--card);
  border: 1px solid rgba(140, 126, 108, 0.18);
  border-radius: var(--r-md);
  padding: 12px 8px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: all 0.2s var(--ease-out);
  cursor: pointer;
}
.hex-card.bad {
  border-color: rgba(224, 73, 60, 0.4);
  background: linear-gradient(135deg, #fffdf9, #fff5f4);
  animation: dangerPulse 1.6s ease-in-out infinite;
}
.hex-card.warn {
  border-color: rgba(226, 143, 27, 0.4);
  background: linear-gradient(135deg, #fffdf9, #fffbf4);
  animation: warnPulse 1.8s ease-in-out infinite;
}
.hex-card.good {
  border-color: rgba(76, 175, 80, 0.35);
}
.hex-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.hex-ico {
  font-size: 20px;
  animation: float 3s ease-in-out infinite;
}
.hex-card.bad .hex-ico {
  animation: shake 0.8s ease-in-out infinite;
}
.hex-val {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  line-height: 1.1;
  margin-top: 3px;
}
.hex-card.bad .hex-val {
  color: var(--danger);
}
.hex-card.warn .hex-val {
  color: #b06f12;
}
.hex-val .u {
  font-size: 12px;
  font-weight: 400;
  color: var(--text-secondary);
}
.hex-label {
  font-size: 10px;
  color: var(--text-secondary);
  margin-top: 3px;
  letter-spacing: 0.3px;
  font-weight: 500;
}
.hex-bar {
  height: 5px;
  background: rgba(140, 126, 108, 0.12);
  border-radius: var(--r-pill);
  margin-top: 5px;
  overflow: hidden;
}
.hex-bar i {
  display: block;
  height: 100%;
  border-radius: var(--r-pill);
  transition: width 0.5s var(--ease-out);
}
.hex-card.bad .hex-bar i {
  background: linear-gradient(90deg, #b8403a, #e0493c);
}
.hex-card.warn .hex-bar i {
  background: linear-gradient(90deg, #b06f12, #e28f1b);
}
.hex-card.good .hex-bar i {
  background: linear-gradient(90deg, #3d8b40, #4caf50);
}
.hex-spark {
  height: 14px;
  margin-top: 4px;
}
.hex-spark path {
  fill: none;
  stroke-width: 1.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  animation: sparklineDraw 1s var(--ease-out) forwards;
}

/* ── 副体征 ── */
.sub-vitals {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
}
.sv {
  flex: 1;
  background: var(--card-alt);
  border: 1px solid rgba(140, 126, 108, 0.2);
  border-radius: var(--r-md);
  padding: 8px 10px;
  text-align: center;
}
.sv .v {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
}
.sv .l {
  font-size: 9px;
  color: var(--text-secondary);
  margin-top: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
}

/* ── 今日时间轴 ── */
.timeline {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-bottom: 14px;
  padding: 8px 10px;
  background: rgba(140, 126, 108, 0.05);
  border-radius: var(--r-md);
  border: 1px solid rgba(140, 126, 108, 0.15);
}
.tl-wrap {
  flex: 1;
  position: relative;
  padding-bottom: 14px;
  cursor: pointer;
}
.tl-seg {
  height: 8px;
  border-radius: 2px;
  background: rgba(140, 126, 108, 0.15);
  position: relative;
  transition: all 0.3s var(--ease-out);
}
.tl-seg.passed {
  background: linear-gradient(90deg, var(--accent), var(--accent-light));
  opacity: 0.5;
}
.tl-seg.current {
  background: linear-gradient(90deg, var(--accent), var(--accent-light));
  box-shadow: 0 0 8px var(--accent);
  animation: breathe 2s ease-in-out infinite;
}
.tl-label {
  font-size: 8px;
  color: var(--text-secondary);
  position: absolute;
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
}

/* ── 成就统计 ── */
.achievement-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
  margin-bottom: 14px;
  cursor: pointer;
}
.ach-item {
  background: linear-gradient(135deg, rgba(201, 168, 76, 0.06), #fffdf9);
  border: 1px solid rgba(201, 168, 76, 0.2);
  border-radius: var(--r-md);
  padding: 8px 10px;
  text-align: center;
  transition: transform 0.2s var(--ease-out);
}
.achievement-row:hover .ach-item {
  transform: translateY(-2px);
}
.ach-icon {
  font-size: 18px;
}
.ach-val {
  font-family: var(--font-data);
  font-size: 15px;
  font-weight: 700;
  color: var(--spirit-gold);
  margin-top: 2px;
}
.ach-lbl {
  font-size: 9px;
  color: var(--text-secondary);
  margin-top: 1px;
}

/* ── 推荐路线 ── */
.route-card {
  background: linear-gradient(135deg, rgba(52, 138, 167, 0.06), #fffdf9);
  border: 1px solid rgba(52, 138, 167, 0.2);
  border-left: 4px solid var(--info);
  border-radius: var(--r-md);
  padding: 12px 14px;
  margin-bottom: 14px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: transform 0.2s var(--ease-out);
}
.route-card:hover {
  transform: translateY(-2px);
}
.route-head {
  font-size: 11px;
  color: var(--text-secondary);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.route-text {
  font-size: 12px;
  line-height: 1.7;
  color: var(--text);
}

.today {
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: var(--r-md);
  padding: 11px 13px;
  margin-bottom: 14px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-secondary);
}
.today b {
  color: var(--accent);
  font-family: var(--font-display);
}

.oplog {
  background: linear-gradient(135deg, #f3ece0, #fffdf9);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 10px 12px;
  margin-bottom: 12px;
  box-shadow: var(--shadow-sm);
}
.oplog-h {
  font-size: 10px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 7px;
  letter-spacing: 0.3px;
}
.oplog-h .dot-live {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--success);
  box-shadow: 0 0 0 2px rgba(76, 175, 80, 0.2);
  animation: breathe 2s ease-in-out infinite;
}
.oplog-item {
  font-size: 11px;
  line-height: 1.5;
  padding: 3px 0;
  display: flex;
  gap: 7px;
  color: var(--text-secondary);
}
.oplog-item .t {
  font-family: var(--font-data);
  font-size: 9px;
  color: var(--accent);
  flex-shrink: 0;
  padding-top: 1px;
}
.oplog-item:not(:last-child) {
  border-bottom: 1px dotted rgba(140, 126, 108, 0.2);
}

/* ── 入口网格 ── */
.entry-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 9px;
}
.entry {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 14px 6px;
  text-align: center;
  cursor: pointer;
  transition: all 0.15s var(--ease-out);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    0 1px 3px rgba(44, 37, 32, 0.07),
    0 2px 6px rgba(44, 37, 32, 0.05);
  position: relative;
}
.entry:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: var(--accent-light);
}
.entry:active {
  transform: translateY(-1px);
}
.entry .e-ico {
  font-size: 26px;
  display: block;
  line-height: 1;
  transition: transform 0.2s var(--ease-out);
}
.entry:hover .e-ico {
  transform: scale(1.12);
}
.entry .e-label {
  font-size: 11px;
  margin-top: 6px;
  font-weight: 500;
}
.entry .e-badge {
  position: absolute;
  top: 6px;
  right: 6px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: var(--r-pill);
  background: var(--accent);
  color: #fff;
  font-size: 9px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: fadeInScale 0.2s var(--ease-out);
}

.term-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, #f6efe4, #fffdf9);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 11px 13px;
  margin: 18px 0 4px;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all 0.15s var(--ease-out);
  position: relative;
}
.term-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
  background: var(--accent);
  opacity: 0.7;
}
.term-card:hover {
  border-color: var(--accent-light);
  box-shadow: var(--shadow);
  transform: translateY(-1px);
}
.term-card .tc-l {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 500;
}
.term-card .tc-l .tc-ico {
  font-size: 16px;
}
.term-card .tc-arrow {
  font-size: 11px;
  color: var(--accent);
}

/* 危险操作区 */
.danger-zone {
  margin-top: 22px;
  padding-top: 14px;
  border-top: 1px dashed rgba(140, 126, 108, 0.25);
  text-align: center;
}
.dz-link {
  font-size: 11px;
  color: var(--danger);
  cursor: pointer;
  opacity: 0.65;
  user-select: none;
  transition: opacity 0.15s;
  display: inline-block;
  padding: 4px 10px;
}
.dz-link:hover {
  opacity: 1;
  text-decoration: underline;
}

.reset-card {
  background: var(--card);
  border: 2px solid var(--danger);
  border-radius: var(--r-md);
  padding: 16px;
  margin: 4px 0 8px;
  text-align: left;
  box-shadow: 0 4px 18px rgba(184, 64, 58, 0.15);
  animation: slideUp 0.2s var(--ease-out);
}
.rc-title {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 700;
  color: var(--danger);
  margin-bottom: 10px;
  text-align: center;
}
.rc-body {
  font-size: 12px;
  line-height: 1.7;
  color: var(--text);
}
.rc-body p {
  margin: 0 0 6px;
}
.rc-body p:last-child {
  margin-bottom: 0;
}
.rc-warn {
  color: var(--danger);
  font-weight: 600;
}
.rc-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}
.rc-btn {
  flex: 1;
  padding: 8px 10px;
  border-radius: var(--r-md);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid;
  transition: all 0.12s;
  font-family: inherit;
}
.rc-btn.cancel {
  background: var(--card-alt);
  color: var(--text);
  border-color: var(--border);
}
.rc-btn.cancel:hover {
  background: var(--nav);
}
.rc-btn.confirm {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.rc-btn.confirm:hover {
  background: #9a3329;
  border-color: #9a3329;
}
